CREATE TYPE public.app_role AS ENUM ('student','reviewer','admin');
CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, full_name text NOT NULL DEFAULT '', phone text NOT NULL DEFAULT '', tax_id text NOT NULL DEFAULT '', updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, UPDATE ON public.profiles TO authenticated;
GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY profile_own_read ON public.profiles FOR SELECT TO authenticated USING (id=auth.uid());
CREATE POLICY profile_own_update ON public.profiles FOR UPDATE TO authenticated USING(id=auth.uid()) WITH CHECK(id=auth.uid());
CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, role public.app_role NOT NULL DEFAULT 'student', UNIQUE(user_id,role));
GRANT SELECT ON public.user_roles TO authenticated;
GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_roles ON public.user_roles FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE FUNCTION public.has_role(_user_id uuid,_role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_user_id AND role=_role) $$;
REVOKE ALL ON FUNCTION public.has_role(uuid,public.app_role) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.has_role(uuid,public.app_role) TO authenticated,service_role;
CREATE FUNCTION public.create_account_profile() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.profiles(id,full_name) VALUES(NEW.id,left(coalesce(NEW.raw_user_meta_data->>'full_name',''),100)); INSERT INTO public.user_roles(user_id,role) VALUES(NEW.id,'student'); RETURN NEW; END $$;
CREATE TRIGGER account_profile_created AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.create_account_profile();
CREATE POLICY admin_profiles_read ON public.profiles FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.commerce_products (id text PRIMARY KEY, slug text UNIQUE NOT NULL, title text NOT NULL, kind text NOT NULL, price_cents integer NOT NULL CHECK(price_cents>=0), active boolean NOT NULL DEFAULT false, updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.commerce_products TO anon,authenticated;
GRANT INSERT,UPDATE ON public.commerce_products TO authenticated;
GRANT ALL ON public.commerce_products TO service_role;
ALTER TABLE public.commerce_products ENABLE ROW LEVEL SECURITY;
CREATE POLICY public_products ON public.commerce_products FOR SELECT TO anon,authenticated USING(active);
CREATE POLICY admin_products ON public.commerce_products FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.commerce_terms (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), version text UNIQUE NOT NULL, body text NOT NULL, published boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.commerce_terms TO anon,authenticated;
GRANT INSERT,UPDATE ON public.commerce_terms TO authenticated;
GRANT ALL ON public.commerce_terms TO service_role;
ALTER TABLE public.commerce_terms ENABLE ROW LEVEL SECURITY;
CREATE POLICY published_terms ON public.commerce_terms FOR SELECT TO anon,authenticated USING(published);
CREATE POLICY admin_terms ON public.commerce_terms FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.commerce_coupons (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), code text UNIQUE NOT NULL CHECK(code=upper(code)), kind text NOT NULL CHECK(kind IN('percent','fixed')), value integer NOT NULL CHECK(value>0), active boolean NOT NULL DEFAULT false, expires_at timestamptz, max_uses integer CHECK(max_uses>0), uses integer NOT NULL DEFAULT 0, CHECK(kind<>'percent' OR value<=100));
GRANT SELECT,INSERT,UPDATE ON public.commerce_coupons TO authenticated;
GRANT ALL ON public.commerce_coupons TO service_role;
ALTER TABLE public.commerce_coupons ENABLE ROW LEVEL SECURITY;
CREATE POLICY admin_coupons ON public.commerce_coupons FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.commerce_orders (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, request_id uuid NOT NULL, status text NOT NULL DEFAULT 'awaiting_integration' CHECK(status IN('awaiting_integration','pending','paid','free','cancelled','cancellation_requested','refunded','rejected')), subtotal_cents integer NOT NULL CHECK(subtotal_cents>=0), discount_cents integer NOT NULL DEFAULT 0 CHECK(discount_cents>=0), total_cents integer NOT NULL CHECK(total_cents>=0), coupon_id uuid REFERENCES public.commerce_coupons(id), payment_method text NOT NULL CHECK(payment_method IN('pix','boleto','card','free')), installments integer NOT NULL DEFAULT 1 CHECK(installments BETWEEN 1 AND 6), terms_id uuid NOT NULL REFERENCES public.commerce_terms(id), terms_accepted_at timestamptz NOT NULL DEFAULT now(), terms_ip inet, source text NOT NULL DEFAULT 'direct', conversion_tags jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), cancelled_at timestamptz, cancellation_reason text, confirmation_email_status text NOT NULL DEFAULT 'not_configured', UNIQUE(user_id,request_id));
GRANT SELECT ON public.commerce_orders TO authenticated;
GRANT ALL ON public.commerce_orders TO service_role;
ALTER TABLE public.commerce_orders ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_orders ON public.commerce_orders FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE POLICY admin_orders ON public.commerce_orders FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.commerce_order_items (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), order_id uuid NOT NULL REFERENCES public.commerce_orders(id), product_id text NOT NULL REFERENCES public.commerce_products(id), title text NOT NULL, price_cents integer NOT NULL CHECK(price_cents>=0), UNIQUE(order_id,product_id));
GRANT SELECT ON public.commerce_order_items TO authenticated;
GRANT ALL ON public.commerce_order_items TO service_role;
ALTER TABLE public.commerce_order_items ENABLE ROW LEVEL SECURITY;
CREATE POLICY order_items_read ON public.commerce_order_items FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.commerce_orders o WHERE o.id=order_id AND (o.user_id=auth.uid() OR public.has_role(auth.uid(),'admin'))));
CREATE TABLE public.commerce_enrollments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, product_id text NOT NULL REFERENCES public.commerce_products(id), order_id uuid NOT NULL REFERENCES public.commerce_orders(id), status text NOT NULL DEFAULT 'active' CHECK(status IN('active','cancelled')), enrolled_at timestamptz NOT NULL DEFAULT now(), expires_at timestamptz, UNIQUE(user_id,product_id));
GRANT SELECT ON public.commerce_enrollments TO authenticated;
GRANT ALL ON public.commerce_enrollments TO service_role;
ALTER TABLE public.commerce_enrollments ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_enrollments ON public.commerce_enrollments FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE POLICY admin_enrollments ON public.commerce_enrollments FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin'));
CREATE FUNCTION public.create_commerce_order(p_user uuid,p_request uuid,p_products text[],p_coupon text,p_method text,p_installments integer,p_terms uuid,p_ip inet,p_source text,p_tags jsonb) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE v_id uuid; v_sub integer; v_discount integer:=0; v_total integer; v_coupon public.commerce_coupons%ROWTYPE; v_count integer;
BEGIN
 SELECT id INTO v_id FROM public.commerce_orders WHERE user_id=p_user AND request_id=p_request; IF v_id IS NOT NULL THEN RETURN v_id; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(p_user::text,0));
 SELECT id INTO v_id FROM public.commerce_orders WHERE user_id=p_user AND request_id=p_request; IF v_id IS NOT NULL THEN RETURN v_id; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.profiles WHERE id=p_user AND length(trim(full_name))>=2) THEN RAISE EXCEPTION 'Complete seu nome na conta.'; END IF;
 IF cardinality(p_products) NOT BETWEEN 1 AND 10 OR cardinality(p_products)<>(SELECT count(DISTINCT x) FROM unnest(p_products) x) THEN RAISE EXCEPTION 'Seleção de cursos inválida.'; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.commerce_terms WHERE id=p_terms AND published) THEN RAISE EXCEPTION 'Os termos ainda não foram publicados.'; END IF;
 IF p_method NOT IN('pix','boleto','card') OR p_installments NOT BETWEEN 1 AND 6 OR (p_method<>'card' AND p_installments<>1) THEN RAISE EXCEPTION 'Forma de pagamento inválida.'; END IF;
 IF EXISTS(SELECT 1 FROM public.commerce_enrollments WHERE user_id=p_user AND product_id=ANY(p_products) AND status='active') THEN RAISE EXCEPTION 'Você já tem matrícula em um dos cursos selecionados.'; END IF;
 SELECT count(*),coalesce(sum(price_cents),0) INTO v_count,v_sub FROM public.commerce_products WHERE id=ANY(p_products) AND active;
 IF v_count<>cardinality(p_products) THEN RAISE EXCEPTION 'Curso indisponível para matrícula.'; END IF;
 IF length(trim(coalesce(p_coupon,'')))>0 THEN
 SELECT * INTO v_coupon FROM public.commerce_coupons WHERE code=upper(trim(p_coupon)) FOR UPDATE;
 IF NOT FOUND OR NOT v_coupon.active OR (v_coupon.expires_at IS NOT NULL AND v_coupon.expires_at<=now()) OR (v_coupon.max_uses IS NOT NULL AND v_coupon.uses>=v_coupon.max_uses) THEN RAISE EXCEPTION 'Cupom inválido ou indisponível.'; END IF;
 v_discount:=least(v_sub,CASE WHEN v_coupon.kind='percent' THEN (v_sub::bigint*v_coupon.value/100)::integer ELSE v_coupon.value END);
 END IF;
 v_total:=v_sub-v_discount;
 INSERT INTO public.commerce_orders(user_id,request_id,status,subtotal_cents,discount_cents,total_cents,coupon_id,payment_method,installments,terms_id,terms_ip,source,conversion_tags) VALUES(p_user,p_request,CASE WHEN v_total=0 THEN 'free' ELSE 'awaiting_integration' END,v_sub,v_discount,v_total,v_coupon.id,CASE WHEN v_total=0 THEN 'free' ELSE p_method END,p_installments,p_terms,p_ip,left(coalesce(p_source,'direct'),160),coalesce(p_tags,'{}')) RETURNING id INTO v_id;
 INSERT INTO public.commerce_order_items(order_id,product_id,title,price_cents) SELECT v_id,id,title,price_cents FROM public.commerce_products WHERE id=ANY(p_products);
 IF v_coupon.id IS NOT NULL THEN UPDATE public.commerce_coupons SET uses=uses+1 WHERE id=v_coupon.id; END IF;
 IF v_total=0 THEN INSERT INTO public.commerce_enrollments(user_id,product_id,order_id) SELECT p_user,id,v_id FROM public.commerce_products WHERE id=ANY(p_products) ON CONFLICT(user_id,product_id) DO UPDATE SET order_id=EXCLUDED.order_id,status='active',enrolled_at=now(),expires_at=NULL; END IF;
 RETURN v_id;
END $$;
REVOKE ALL ON FUNCTION public.create_commerce_order(uuid,uuid,text[],text,text,integer,uuid,inet,text,jsonb) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.create_commerce_order(uuid,uuid,text[],text,text,integer,uuid,inet,text,jsonb) TO service_role;
CREATE FUNCTION public.cancel_commerce_order(p_user uuid,p_order uuid,p_reason text) RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE o public.commerce_orders%ROWTYPE; next_status text;
BEGIN
 SELECT * INTO o FROM public.commerce_orders WHERE id=p_order AND user_id=p_user FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Pedido não encontrado.'; END IF;
 IF o.status IN('cancelled','refunded','cancellation_requested') THEN RETURN o.status; END IF;
 next_status:=CASE WHEN o.status='paid' THEN 'cancellation_requested' ELSE 'cancelled' END;
 UPDATE public.commerce_orders SET status=next_status,cancelled_at=now(),cancellation_reason=left(p_reason,1000),confirmation_email_status='not_configured' WHERE id=p_order;
 IF next_status='cancelled' THEN
 UPDATE public.commerce_enrollments SET status='cancelled' WHERE order_id=p_order;
 IF o.coupon_id IS NOT NULL THEN UPDATE public.commerce_coupons SET uses=greatest(0,uses-1) WHERE id=o.coupon_id; END IF;
 END IF;
 RETURN next_status;
END $$;
REVOKE ALL ON FUNCTION public.cancel_commerce_order(uuid,uuid,text) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.cancel_commerce_order(uuid,uuid,text) TO service_role;